/** Lightweight modal shell. Scientific code/data remain in the lazy viewer import. */
export function skyViewerHTML({variant='sky'}={}){const telescope=variant==='telescope';return `<div class="sky-vista sky-scientific-vista${telescope?' sky-telescope-vista':''}" id="sky-content"><canvas data-sky-canvas role="img" tabindex="0" aria-label="선택한 장소와 시각의 하늘. 드래그하거나 방향키로 둘러보고 Home 키로 남쪽 시점으로 돌아와요." aria-describedby="sky-explore-help sky-note"></canvas><div class="sky-heading"><div><span class="sky-eyebrow">${telescope?'장소와 시각을 따라 우주를 보아요':'잠깐, 하늘을 보아요'}</span><h2 id="modal-title">${telescope?'천문대 망원경':'섬 위의 하늘'}</h2><p data-sky-clock role="status">하늘을 준비하고 있어요</p></div><button class="modal-x" data-close aria-label="하늘 보기 닫기">×</button></div><div data-sky-observer-host></div><div class="sky-foot"><p id="sky-explore-help" class="sky-explore-help">가만히 머물러도 좋아요 · 드래그 / 방향키로 둘러보기</p><div class="sky-actions"><button data-sky-guides aria-pressed="false">별자리 선</button><button data-sky-pause aria-pressed="false">구름 멈추기</button><button data-sky-reset aria-label="남쪽 하늘로 시점 되돌리기">남쪽으로</button></div><p class="sky-notice" id="sky-note" data-sky-note>위치를 계산하는 동안 잠시 기다려 주세요</p>${telescope?'<p class="sky-notice sky-telescope-safety">실제 망원경으로 태양을 직접 보지 마세요. 태양 관측에는 전용 장비와 전문가의 안내가 필요해요. <a href="https://science.nasa.gov/eclipses/safety/" target="_blank" rel="noopener">NASA 안전 안내</a></p>':''}</div></div>`;}
